# Eindtoets 3 Inkoop en recht: eigen vragen over alle weken (week 0, versie E3).
W = 0
I, R = "Inkoop", "Recht"
EIND_TITEL = "Waterschap Maas en Linge en Zorggroep De Linde"
EIND_UITLEG = "Een derde vaste toets met nieuwe vragen over alle weken, met onderwerpen die in de andere toetsen minder aan bod komen. De casussen gaan over een dijkversterking en de aankoop van tilliften."

# ---------- Inkoop MC ----------
mc("ire3-i01", W, I, "Een wasserij heeft € 240.000 vaste kosten per jaar en verwerkt 400.000 kilo wasgoed. De variabele kosten zijn € 0,90 per kilo. Wat is de kostprijs per kilo?",
   ["€ 1,50", "€ 0,90", "€ 0,60", "€ 1,88"], 0,
   "Vaste kosten per kilo: € 240.000 / 400.000 = € 0,60. Plus € 0,90 variabel geeft een kostprijs van € 1,50. € 1,88 is al een verkoopprijs met 20% marge van de verkoopprijs (100/80 × € 1,50); de winst komt pas na de kostprijs.")
mc("ire3-i02", W, I, "Een cateraar runt het bedrijfsrestaurant van een verzekeraar. Welke kosten zijn voor de cateraar indirecte kosten (overhead)?",
   ["De ingrediënten voor de lunches", "De uren van de kok in het restaurant", "Het salaris van de planner op het hoofdkantoor", "De wegwerpbekers die per kop koffie nodig zijn"], 2,
   "Directe kosten horen 100% bij het product of de dienst: ingrediënten, bekers en de uren van de kok op locatie. Indirecte kosten worden voor alle opdrachten gemaakt zonder duidelijke relatie met één opdracht, zoals de planner op het hoofdkantoor (vergelijk de receptioniste op de slide).")
mc("ire3-i03", W, I, "Een gemeente koopt haar bedrijfskleding voortaan alleen bij leveranciers binnen Nederland. Welk nadeel hoort volgens de les bij deze keuze voor lokaal inkopen?",
   ["Langere levertijden en meer voorraad", "Meer gedoe met douane en valuta", "Je mist mogelijk betere of goedkopere producten", "Meer cultuurverschillen in het contact"], 2,
   "Lokaal inkopen geeft juist korte levertijden en minder gedoe met douane, valuta en cultuurverschillen. Het nadeel: je kunt naast de beste producten grijpen, en kostprijzen buiten West-Europa liggen vaak lager.")
mc("ire3-i04", W, I, "Welk kenmerk hoort volgens de les vooral bij privaat inkopen, zoals bij een bank of een kledingwinkel?",
   ["Maatschappelijke doelstellingen en politieke gevoeligheid",
    "Aanbestedingswetgeving als juridisch kader",
    "Onderhandelen, marktkennis en leveringsrisico's uitsluiten",
    "Verantwoording over belastinggeld aan de gemeenteraad"], 2,
   "Privaat inkopen draait om winst maken, onderhandelen, kennis van de markt en leveringsrisico's uitsluiten, vaak ad hoc en met meer focus op prijs. Maatschappelijke doelen, aanbestedingsrecht en politieke gevoeligheid horen bij publiek inkopen.")
mc("ire3-i05", W, I, "Een fietsenfabrikant koopt aluminium frames voor zijn fietsen en laat zijn kantoor schoonmaken. Hoe deel je deze inkoop in?",
   ["Frames direct (primair), schoonmaak indirect",
    "Frames indirect, schoonmaak direct (primair)",
    "Allebei direct, want beide zijn nodig voor de bedrijfsvoering",
    "Allebei indirect, want beide worden extern ingekocht"], 0,
   "Directe (primaire) inkoop is productgerelateerd: de frames komen in de fiets terecht. Indirecte inkoop is niet productgerelateerd; facilitaire inkoop zoals schoonmaak is meestal indirect.")
mc("ire3-i06", W, I, "Een inkoper werkt een ethisch dilemma uit met het NEVI-stappenplan. Het dilemma is benoemd, en de bekende feiten en de ontbrekende informatie zijn op een rij gezet. Wat is de volgende stap?",
   ["Bedenk minimaal twee oplossingen", "Bepaal welke waarden en belangen een rol spelen", "Kies de optie met de laagste prijs", "Houd een pitch van één minuut voor de directie"], 1,
   "Het stappenplan: (1) wat is het dilemma, (2) welke feiten weten we en welke informatie missen we, (3) welke waarden en belangen spelen een rol, (4) minimaal twee oplossingen, (5) de beste optie, (6) drie argumenten, (7) een pitch, (8) reflectie. Ethische dilemma's vragen een zorgvuldige en transparante afweging.")
mc("ire3-i07", W, I, "Een gemeente kiest bewust voor een schoonmaakbedrijf dat mensen met een afstand tot de arbeidsmarkt in dienst neemt en eerlijke lonen in de keten borgt, ook al is het iets duurder. Bij welk principe van de NEVI-gedragscode past dit het best?",
   ["Maatschappelijke waarde", "Integriteit en objectiviteit", "Deskundigheid en verantwoording", "Effectieve concurrentie"], 0,
   "Maatschappelijke waarde: meerwaarde voor organisatie én maatschappij, met een langetermijnvisie en aandacht voor duurzaamheid, mensenrechten en sociale omstandigheden in de keten. Effectieve concurrentie is een aanbestedingsbeginsel, geen NEVI-principe.")
mc("ire3-i08", W, I, "Een gemeente verlengt het contract met een slecht presterende glazenwasser niet en verdeelt het werk over twee leveranciers die het wel goed doen. Bij welk begrip uit de les hoort dit?",
   ["Leveranciersbeleid: relaties verbeteren, op peil houden of afbouwen",
    "Maverick buying: inkopen buiten de contracten om",
    "Co-makership: de leverancier wordt verantwoordelijk voor een deel",
    "Make-or-buy: de keuze tussen zelf doen of uitbesteden"], 0,
   "Leveranciersbeleid is gericht op het systematisch verbeteren, op peil houden of afbouwen van relaties met leveranciers. Hier bouwt de gemeente een relatie af en verschuift het werk naar leveranciers die goed presteren.")

# ---------- Recht MC ----------
mc("ire3-r01", W, R, "Defensie wil helikopters kopen die ook voor civiele reddingsvluchten bruikbaar zijn, en wil dat zonder aanbesteding doen met een beroep op de defensie-uitzondering. Kan dat?",
   ["Ja, alles wat Defensie aanschaft valt automatisch onder art. 346 VWEU en art. 2.23 Aw",
    "Nee, uitzonderingen zijn strikt; ook civiel bruikbaar materieel valt er niet zomaar onder",
    "Ja, want helikopters zijn leveringen en daarvoor geldt geen Europese aanbestedingsplicht",
    "Nee, want het ministerie van Defensie is geen aanbestedende dienst in de zin van de Aw"], 1,
   "Uitzonderingen worden strikt uitgelegd en wie er een beroep op doet, moet ze bewijzen. Echte defensieopdrachten (zoals de JSF) vallen eronder, maar wat ook civiel bruikbaar is niet zomaar (Agusta). Defensie hoort bij de Staat en is dus wel een aanbestedende dienst.")
mc("ire3-r02", W, R, "Hoe kan een aanbestedende dienst volgens de les de minimumtermijn voor inschrijving bij de openbare procedure verkorten?",
   ["Met een vooraankondiging, en met 5 dagen als elektronisch inschrijven kan",
    "Door de opdracht op te splitsen in percelen onder de drempel",
    "Door de Alcatel-termijn van 20 dagen in te korten tot 15 dagen",
    "Door alleen inschrijvers uit Nederland toe te laten tot de procedure"], 0,
   "De termijn van 45 dagen (art. 2.71 Aw) kan korter met een vooraankondiging (art. 2.71 lid 5 en 6) en met 5 dagen als elektronisch inschrijven mogelijk is (art. 2.74b). Bij een dringende reden die niet aan de dienst zelf te wijten is, kan het ook (art. 2.74). Opsplitsen om onder de drempel te blijven is verboden.")
mc("ire3-r03", W, R, "Wat is een elektronische veiling volgens de Aanbestedingswet?",
   ["Een zelfstandige procedure naast de openbare en niet-openbare",
    "Een onderdeel binnen een andere procedure (art. 2.117 Aw)",
    "Een nationale procedure voor opdrachten onder de drempel",
    "Een raamovereenkomst waarbij leveranciers online bieden"], 1,
   "De elektronische veiling (art. 2.117 Aw) staat in het overzicht van procedures, maar is geen zelfstandige procedure: het is een onderdeel van een andere procedure. Hetzelfde geldt eigenlijk voor de raamovereenkomst, die geen echte procedure is.")
mc("ire3-r04", W, R, "Een gemeente gunt een concessie voor de exploitatie van de stadsparkeergarages, met een verwachte omzet van € 9 miljoen. Wat geldt voor de procedure?",
   ["Zij moet de openbare procedure van art. 2.26 Aw volgen",
    "Vormvrij, mits zij de opzet beschrijft en de stappen documenteert",
    "Geen enkele, want concessies zijn uitgezonderd van de Aw",
    "Alleen de concurrentiegerichte dialoog is dan toegestaan"], 1,
   "€ 9 miljoen ligt boven de concessiedrempel van € 5.404.000, dus Deel 2A Aw geldt. De procedure is vormvrij (art. 2a.30 Aw), mits de dienst de organisatie van de procedure beschrijft en de stappen documenteert. Onderhandelen mag zolang de criteria gelijk blijven; aankondigen gaat via TenderNed.")
mc("ire3-r05", W, R, "Een hogeschool bestelt telefonisch 40 whiteboards, maar partijen spreken geen prijs af. De leverancier stuurt achteraf een factuur. Wat geldt?",
   ["Er is geen koop gesloten, want de prijs is een essentieel punt",
    "De hogeschool moet een redelijke prijs betalen (art. 7:4 BW)",
    "Er is niets op papier, dus de hogeschool hoeft niets te betalen",
    "De leverancier mag elke prijs vragen die hij wil"], 1,
   "Een koop kan mondeling, schriftelijk en stilzwijgend ontstaan (vormvrijheid). Is er geen prijs afgesproken, dan is de koper een redelijke prijs verschuldigd (art. 7:4 BW); de verbintenis is zo bepaalbaar (art. 6:227 BW).")
mc("ire3-r06", W, R, "Een gemeente en een ICT-leverancier willen tijdens de onderhandelingen afspraken vastleggen. Met welk middel moeten zij volgens de les oppassen, omdat het partijen al bindt?",
   ["Een gentlemen's agreement", "Een voorovereenkomst", "Een letter of intent met een voorbehoud", "Een gespreksverslag zonder handtekeningen"], 1,
   "Om gerechtvaardigd vertrouwen te voorkomen kun je werken met een gentlemen's agreement, een letter of intent of een voorovereenkomst, maar pas op: een voorovereenkomst bindt al. Een voorbehoud (zoals instemming van het bestuur) helpt juist om niet te snel gebonden te raken.")
mc("ire3-r07", W, R, "Een schoonmaakbedrijf leent van de gemeente een schrobmachine en gebruikt die in het stadhuis. Wat is het schoonmaakbedrijf ten aanzien van de machine?",
   ["Houder: het houdt de machine voor een ander", "Bezitter: het houdt de machine voor zichzelf", "Eigenaar door bezitsverschaffing", "Beschikkingsbevoegde vervreemder"], 0,
   "Een houder houdt een zaak voor een ander (hier de gemeente), een bezitter houdt de zaak voor zichzelf. De gemeente blijft eigenaar en bezitter. Het onderscheid is belangrijk bij levering zonder feitelijke overdracht (art. 3:115 BW), zoals brevi manu als het bedrijf de machine later koopt.")
mc("ire3-r08", W, R, "Een particulier koopt bij een meubelzaak een kast en betaalt de factuur niet op tijd. Welke schadevergoeding kan de meubelzaak vorderen voor de vertraging?",
   ["De wettelijke rente (art. 6:119 BW)", "Het positief contractsbelang van de koop", "Een vaste boete van 15% van de koopprijs", "Niets, dat is bij consumentenkoop uitgesloten"], 0,
   "Betaalt de koper niet, dan kan de verkoper schadevergoeding in de vorm van de wettelijke rente vorderen (art. 6:119 BW), en daarnaast nakoming of ontbinding, of het recht van reclame. Let op: bij consumentenkoop verjaart de vordering tot betaling na twee jaar (art. 7:28 BW).")

# ---------- open ----------
op("ire3-o1", W, I, "Leg voor de drie marktvormen uit hoeveel invloed een inkoper aan de vraagzijde heeft op de prijs, met per marktvorm een FM-voorbeeld. Wat betekent je machtspositie voor je inkoopstrategie? Leg ook uit waarom een leverancier met veel onbenutte capaciteit je onderhandelingspositie versterkt.",
   "Monopolie aan de vraagzijde (één vrager): de inkoper heeft veel macht, bijvoorbeeld een fabriek die als enige in de regio bedrijfskleding afneemt. Oligopolie (een beperkte groep vragers die elkaars prijzen volgen): enige invloed, bijvoorbeeld ziekenhuizen in een regio die samen inkopen. Polypolie (veel vragers): geen invloed op de prijs, de inkoper volgt de markt, bijvoorbeeld bij kantoorartikelen. Strategie: hoe meer macht, hoe meer je kunt onderhandelen; met weinig macht kun je volume bundelen, bijvoorbeeld via horizontale samenwerking in een inkoopcombinatie, of efficiënt tegen marktprijs inkopen. Onbenutte capaciteit: de leverancier wil graag orders, want elke prijs boven de variabele kosten draagt bij aan zijn vaste kosten. Dat geeft de inkoper onderhandelingsruimte (capaciteitsbenutting is een van de manieren om de kostprijs te achterhalen).",
   ["Drie marktvormen met invloed en voorbeeld", "Gevolg voor de strategie (onderhandelen of bundelen)", "Onbenutte capaciteit uitgelegd met variabele en vaste kosten"])
op("ire3-o2", W, I, "Een hogeschool wil dat het nieuwe schoonmaakcontract bijdraagt aan haar MVO-beleid, dat op de SDG's is gebaseerd. Leg uit wat de SDG's zijn. Kies twee duurzaamheidsthema's die je goed in een FM-inkoopcontract kunt vangen, en vertaal elk thema naar een eis of KPI met norm. Is jouw voorstel groen of circulair inkopen?",
   "De SDG's (Sustainable Development Goals) zijn de duurzame-ontwikkelingsdoelen van de VN voor 2015-2030; ze vervingen de millenniumdoelen. Organisaties gebruiken ze in hun MVO-beleid en inkopers vertalen ze naar contracten. Thema's die goed te vangen zijn: energie en klimaat (eis: schoonmaakmachines en vervoer zijn elektrisch; KPI: CO2-uitstoot van het vervoer daalt jaarlijks met 10%, gemeten via de kilometerregistratie), afval en grondstoffen (eis: navulsystemen voor middelen; KPI: minimaal 80% van het verpakkingsafval gerecycled, per kwartaal gerapporteerd), arbeidsomstandigheden (eis: cao en eerlijke lonen; KPI: ziekteverzuim onder 5% en een jaarlijkse audit). Groen gaat over minder milieu-impact (elektrische machines, ecologische middelen); circulair over het behouden van de waarde van producten en grondstoffen (navulsystemen, terugname van machines en textiel voor hergebruik). Een voorstel kan dus beide elementen hebben.",
   ["SDG's juist uitgelegd", "Twee thema's met eis of KPI én norm", "Groen en circulair juist onderscheiden en toegepast"])
op("ire3-o3", W, R, "Noor, medewerker van een hogeschool, koopt via een webshop een bureaustoel van € 350 voor thuis. (a) Na tien dagen wil Noor de stoel terugsturen, omdat de kleur tegenvalt. Kan dat? (b) Na vijf maanden breekt de rugleuning. De webshop verwijst naar de fabrikant en zegt dat de garantie van drie maanden voorbij is. Wat zijn Noors rechten? (c) De webshop is vergeten de stoel te factureren en stuurt pas 26 maanden na de aflevering een rekening. Moet Noor nog betalen?",
   "(a) Ja. Het is een consumentenkoop op afstand (art. 6:230g jo. 6:230m BW): Noor heeft een ontbindingsrecht van 14 dagen zonder opgaaf van reden (art. 6:230o BW), met het modelformulier of een andere verklaring. (b) Consumentenkoop (art. 7:5 BW): de regeling is dwingend (art. 7:6) en een garantie neemt de wettelijke rechten niet weg (art. 7:6a); een negatieve garantie werkt dus niet. Een bureaustoel hoort jaren mee te gaan, dus hij is niet conform (art. 7:17). Het gebrek openbaart zich binnen 6 maanden, dus geldt het bewijsvermoeden van art. 7:18 lid 2 (de slide noemt 6 maanden). Noor heeft recht op herstel of vervanging (art. 7:21) en kan daarvoor bij de webshop terecht: de verkoper is het aanspreekpunt, niet de fabrikant. Klagen binnen twee maanden na ontdekking is in ieder geval op tijd (art. 7:23). (c) Nee, in beginsel niet: bij consumentenkoop verjaart de vordering tot betaling na twee jaar (art. 7:28 BW), tenzij de verjaring is gestuit. Er blijft een natuurlijke verbintenis over (art. 6:3 BW): betaalt Noor toch, dan kan dat niet worden teruggevorderd.",
   ["(a) Ontbindingsrecht 14 dagen bij koop op afstand", "(b) Dwingend recht, 7:6a, non-conformiteit en bewijsvermoeden", "(b) Verkoper is aanspreekpunt, art. 7:21", "(c) Verjaring na twee jaar (art. 7:28) en natuurlijke verbintenis"])
op("ire3-o4", W, R, "Elektroservice Oost v.o.f. (15 medewerkers, geen openbare jaarrekening) koopt warmtepompen bij een groothandel en verkoopt en installeert ze bij particulieren. In de algemene voorwaarden van de groothandel staat: (1) 'De groothandel is niet aansprakelijk voor gebreken aan de geleverde zaken.' (2) 'Alle geschillen worden beslecht door arbitrage.' Een particuliere klant heeft na drie maanden een kapotte warmtepomp en spreekt Elektroservice aan. (a) Moet Elektroservice de klant helpen? (b) Kan Elektroservice de groothandel aanspreken ondanks beding 1? (c) Wat betekent beding 2, en hoe verschilt dat van mediation?",
   "(a) Ja. Het is een consumentenkoop (art. 7:5 BW), dus grotendeels dwingend recht. Een warmtepomp die na drie maanden kapot is, is niet conform (art. 7:17); de klant heeft recht op herstel of vervanging (art. 7:21), en het bewijsvermoeden van art. 7:18 lid 2 helpt de klant. Elektroservice is als verkoper het aanspreekpunt. (b) Ja, waarschijnlijk wel. Art. 6:244 BW beschermt de 'beklemde detaillist': die mag niet klem komen te zitten tussen zijn ruimere aansprakelijkheid tegenover de consument en een exoneratie van zijn eigen leverancier. Bovendien valt Elektroservice niet onder art. 6:235 (minder dan 50 personen, geen openbare jaarrekening), dus kan het beding ook worden vernietigd als het onredelijk bezwarend is (art. 6:233 sub a), of via sub b als de AV niet ter hand zijn gesteld. (c) Bij arbitrage beslissen arbiters en is de gewone rechter niet meer bevoegd; dat is vaak sneller en meestal duurder. Bij mediation of een andere vorm van ADR blijft de rechter bevoegd.",
   ["(a) Consumentenkoop, non-conformiteit en art. 7:21", "(b) Beklemde detaillist art. 6:244", "(b) Geen art. 6:235-partij, dus ook 6:233", "(c) Arbitrage tegenover mediation juist uitgelegd"])

# ---------- casus ----------
cs("ire3-c1", W, R, "Waterschap Maas en Linge versterkt een dijk",
   "Waterschap Maas en Linge (fictief) wil 6 kilometer dijk versterken; de geraamde waarde is € 18 miljoen. De dijkgraaf stelt voor het werk op te knippen in vier delen van 1,5 kilometer à € 4,5 miljoen, 'zodat we onder de Europese drempel blijven'. Het waterschap verwacht veel belangstelling van aannemers. In het concept van de aankondiging staat dat het waterschap 'de vijf beste gegadigden' selecteert op ervaring met dijkversterking; hoe de selectiecriteria wegen, wil het pas na de sluiting bepalen. Bij de selectie wil het ook kijken naar de indicatieve prijs die gegadigden opgeven. Na de dijkversterking wil het waterschap voor zes jaar een raamovereenkomst sluiten voor klein onderhoud aan al zijn dijken.",
   [("Is de dijkversterking Europees aanbestedingsplichtig? Beoordeel het voorstel van de dijkgraaf, en geef aan of de percelenregeling hier helpt.",
     "Wie: een waterschap is een territoriaal lichaam en dus aanbestedende dienst (art. 1.1 Aw). Wat: een werk, want het gaat om een civieltechnisch werk met een technische functie (CPV-code 45). Waarde: € 18 miljoen, boven de drempel van € 5.404.000. Opknippen om onder de drempel te blijven mag niet (splitsingsverbod, art. 2.14 Aw); bij percelen tel je de waarde van alle percelen bij elkaar op (art. 2.18 Aw), dus het blijft € 18 miljoen. De percelenregeling helpt niet: bij werken mag je alleen percelen tot € 1.000.000 zonder Europese procedure gunnen, samen maximaal 20% van de totale waarde (art. 2.18 en 2.19 Aw). Conclusie: Europees aanbesteden. In percelen verdelen mag wel (goed voor het mkb), maar dan elk perceel via een Europese procedure.",
     ["Drie W's met werk en € 5.404.000", "Splitsingsverbod en optellen van percelen", "Percelenregeling werken: max € 1 miljoen en 20%"]),
    ("Welke procedure adviseer je? Beoordeel daarnaast de opzet van de selectie, met arresten of artikelen.",
     "De niet-openbare procedure (art. 2.27 Aw): bij veel verwachte gegadigden beperk je met een selectiefase het aantal inschrijvers, met minimaal 5 (art. 2.99 lid 3 Aw). Fouten in de opzet: (1) de weging van de selectiecriteria moet vooraf bekend zijn, niet pas na de sluiting (Universal Bau, C-470/99; transparantie, art. 1.9 Aw). (2) De indicatieve prijs is een gunningscriterium: die gebruiken in de selectiefase mag niet (Commissie/Italië, C-362/90). Selectie gaat over de ondernemer, gunning over de inschrijving, en het zijn aparte stappen (Beentjes, C-31/87).",
     ["Niet-openbare procedure met reden en minimaal 5", "Weging vooraf bekend (Universal Bau)", "Geen prijs in de selectie (Commissie/Italië)"]),
    ("Stel dat na de inschrijving alle inschrijvingen ruim boven het budget liggen. Mag het waterschap met de goedkoopste inschrijver over de prijs onderhandelen? Welke mogelijkheden heeft het wel?",
     "Nee. Na de inschrijving onderhandelen met één inschrijver is in strijd met het gelijkheidsbeginsel (art. 1.8 Aw); niet-acceptabele inschrijvingen moet je afwijzen in plaats van erover te onderhandelen (Deense brug/Storebaelt). Inschrijvingen ver boven het geraamde budget zijn onaanvaardbaar. Dat is een grond om over te stappen op de mededingingsprocedure met onderhandeling of de concurrentiegerichte dialoog, zonder de opdracht fundamenteel te wijzigen (art. 2.28 Aw). Het waterschap kan ook de procedure stoppen en opnieuw aanbesteden met een aangepaste opdracht of een realistischer budget.",
     ["Nee: gelijkheid en Deense brug", "Onaanvaardbare inschrijvingen als grond voor een andere procedure", "Opdracht niet fundamenteel wijzigen of opnieuw aanbesteden"]),
    ("Mag de raamovereenkomst voor klein onderhoud zes jaar duren? En hoe raam je de waarde ervan?",
     "Nee, in beginsel niet. Een raamovereenkomst duurt maximaal 4 jaar (art. 2.140 Aw; zoek het lid na in je bundel), alleen in uitzonderlijke, goed gemotiveerde gevallen langer. Een looptijd van zes jaar 'gewoon omdat het handig is' kan dus niet. De waarde raam je als de totale waarde van alle opdrachten die je onder de raamovereenkomst verwacht te plaatsen, excl. btw en inclusief opties en verlengingen (art. 2.15 lid 2 Aw). Die vergelijk je met de drempel voor werken (€ 5.404.000) of voor diensten (€ 216.000), afhankelijk van wat het onderhoud is.",
     ["Maximaal 4 jaar met art. 2.140", "Raming: totale waarde van alle verwachte opdrachten, incl. opties", "Juiste drempel genoemd"])])
cs("ire3-c2", W, I, "Zorggroep De Linde koopt tilliften",
   "Zorggroep De Linde (fictief, 800 medewerkers) hoeft in deze casus niet aan te besteden. De Linde wil 60 nieuwe tilliften. TilTech B.V. biedt € 4.800 per lift. De inkoper van De Linde schat met een should-cost-analyse: materialen € 1.900, directe arbeid € 900 en overhead € 600 per lift. In de branche is een marge van 25% van de verkoopprijs gebruikelijk, en bij TilTech staat sinds kort een productielijn stil. Na vijf maanden onderhandelen tekenen De Linde en TilTech een letter of intent: 'Partijen zijn pas gebonden na schriftelijke vastlegging en goedkeuring door de raad van bestuur van De Linde.' Twee weken later zegt de inkoopmanager van De Linde tegen TilTech: 'De goedkeuring is een formaliteit, begin maar vast met produceren.' TilTech maakt € 30.000 kosten voor de eerste 20 liften. Dan breekt De Linde de onderhandelingen af, omdat leverancier LiftPlus 10% goedkoper is.",
   [("Welke prijs per lift verwacht de inkoper op basis van de should-cost-analyse? Hoeveel onderhandelingsruimte zie je, en welke informatie uit de casus versterkt de positie van De Linde nog meer?",
     "Kostprijs: € 1.900 + € 900 + € 600 = € 3.400. Met 25% marge van de verkoopprijs: 100/75 × € 3.400 = € 4.533,33 (niet € 3.400 × 1,25 = € 4.250). De offerte van € 4.800 ligt dus ongeveer € 267 per lift hoger, voor 60 liften zo'n € 16.000. De stilstaande productielijn (onbenutte capaciteit) versterkt de positie van De Linde: TilTech wil graag orders, en elke prijs boven de variabele kosten draagt bij aan de vaste kosten. Andere hulpmiddelen: om een openboekcalculatie vragen, benchmarken met andere zorginstellingen, en per kostensoort nagaan of die beïnvloedbaar is (materiaal vaak wel, overhead soms).",
     ["Verkoopprijs € 4.533 met marge van de verkoopprijs", "Ruimte van circa € 267 per lift", "Onbenutte capaciteit uitgelegd"]),
    ("Mocht De Linde de onderhandelingen afbreken? Betrek de letter of intent, en geef aan wat TilTech kan vorderen.",
     "Uitgangspunt is contractvrijheid: afbreken mag, tenzij dat op grond van gerechtvaardigd vertrouwen in een overeenkomst of door andere omstandigheden onaanvaardbaar is (CBB/JPO). Het voorbehoud in de letter of intent moest juist voorkomen dat er te snel vertrouwen ontstond. Maar De Linde hield zich er zelf niet aan: de inkoopmanager noemde de goedkeuring een formaliteit en zei dat TilTech kon gaan produceren. De Linde heeft dus zelf aan het vertrouwen bijgedragen, de onderhandelingen duurden lang, en een goedkopere concurrent is een zwakke reden op dit moment. Waarschijnlijk is het afbreken onrechtmatig. Grondslag: onrechtmatige daad (art. 6:162 BW), want er is nog geen overeenkomst. TilTech kan dooronderhandelen vorderen (lastig als De Linde al met LiftPlus heeft gecontracteerd) of schadevergoeding: in elk geval het negatief contractsbelang (de € 30.000 kosten), en het positief contractsbelang (gederfde winst) alleen bij hoge uitzondering.",
     ["Maatstaf CBB/JPO", "Voorbehoud weegt mee, maar De Linde hield zich er zelf niet aan", "Art. 6:162 BW met negatief en positief contractsbelang"]),
    ("De Linde koopt de tilliften uiteindelijk bij LiftPlus, een wederverkoper van een Duitse fabrikant. Na een jaar knapt bij een lift een draagband door een fabricagefout; een bewoner valt en raakt gewond. Wie is aansprakelijk voor de letselschade van de bewoner, en wat kan De Linde zelf tegen LiftPlus doen?",
     "Voor schade door een gebrekkig product is de producent aansprakelijk (productaansprakelijkheid, art. 6:185 BW), hier de Duitse fabrikant; ook verkopen aan een wederverkoper geldt als in het verkeer brengen. De bijzondere aansprakelijkheid van de verkoper bij consumentenkoop (art. 7:24 BW) speelt hier niet, want De Linde is geen consument. De Linde zelf kan LiftPlus aanspreken op grond van de koopovereenkomst: een tillift met een draagband die na een jaar knapt, is niet conform (art. 7:17 BW). De Linde heeft recht op herstel of vervanging (art. 7:21 BW) en de rechten uit Boek 6, zoals schadevergoeding en ontbinding. Let op de klachtplicht: binnen bekwame tijd klagen (art. 7:23 BW).",
     ["Producent aansprakelijk, art. 6:185 BW", "Non-conformiteit art. 7:17 tegenover LiftPlus", "Rechten art. 7:21, Boek 6 en klachtplicht"]),
    ("De Linde laat LiftPlus ook het onderhoud en de jaarlijkse keuring van alle liften doen. Welke vorm van uitbesteden is dit? Noem twee risico's, en leg uit met welke pijlers van contractmanagement De Linde die risico's beheerst.",
     "Partial (alleen het onderhoud gaat over, niet de hele activiteit) en on-site (LiftPlus werkt op de locaties van De Linde). Risico's: afhankelijkheid van één leverancier, kwaliteitsrisico (de veiligheid van bewoners), verlies van eigen kennis, verlies van regie en verborgen kosten. Beheersen: pijler 2 contractadministratie (keuringsdata, looptijd en verlengingen bewaken), pijler 3 prestatiemanagement (KPI's met normen, zoals 'storingen in 95% van de gevallen binnen 24 uur verholpen' en '100% van de liften op tijd gekeurd', met periodieke evaluaties en bijsturen), en eventueel pijler 4 relatiemanagement (regelmatig overleg, constructief conflicten oplossen).",
     ["Partial en on-site", "Twee risico's van uitbesteden", "Passende pijlers met concrete invulling"])])
